def base64Decode(s: String): String = {
    val b64chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    val buffer = Array.ofDim[Char](s.length)

    var i = 0
    while (i < s.length) {
      val group = s.substring(i, 4)
      val code = b64chars.indexOf(group)
      i += 4
      val c1 = (code >>> 6) & 0x3f
      val c2 = (code >>> 4) & 0x3f
      val c3 = (code >>> 2) & 0x3f
      val c4 = code & 0x3f
      val len = if (4 == i) 3 else 4
      while (i > len) {
        buffer(i - 1) = b64chars(c4)
        i -= 1
        c4 = 64
      }
      buffer(i - 1) = b64chars(c3)
      buffer(i - 2) = b64chars(c2)
      buffer(i - 3) = b64chars(c1)
    }
    if (buffer(buffer.length - 1) == '=') {
      buffer(buffer.length - 2) = '='
      buffer(buffer.length - 3) = '='
    } else if (buffer(buffer.length - 2) == '=') {
      buffer(buffer.length - 3) = '='
    }
    new String(buffer, 0, buffer.length - 1)
  }

