void pop(String descriptor) {
    // Remove the number of abstract types from the output frame stack as described by the descriptor
    int abstractTypes = getAbstractTypesFromDescriptor(descriptor);
    for (int i = 0; i < abstractTypes; i++) {
        outputFrameStack.pop();
    }
}

/**
 * Returns the number of abstract types described by the given descriptor.
 * @param descriptor a type or method descriptor (in which case its argument types are counted).
 */
private int getAbstractTypesFromDescriptor(String descriptor) {
    if (descriptor == null) {
        return 0;
    }

    int abstractTypes = 0;
    for (char c : descriptor.toCharArray()) {
        switch (c) {
            case 'B':
            case 'C':
            case 'S':
            case 'Z':
            case 'I':
            case 'F':
            case 'J':
            case 'D':
                // These are primitive types, which are not abstract
                break;
            case 'L':
                // The start of a generic type, which is always abstract
                abstractTypes++;
                break;
            case 'V':
                // The topmost element, which never gets popped and hence isn't counted
                break;
            default:
                // This is an unexpected character, which shouldn't happen with a valid descriptor
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
        }
    }

    return abstractTypes;
}

