public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path or relative path cannot be null");
    }
    String[] pathParts = path.split("/");
    String[] relativePathParts = relativePath.split("/");
    if (relativePathParts.length == 0) {
        return path;
    }
    StringBuilder newPath = new StringBuilder();
    for (int i = 0; i < relativePathParts.length; i++) {
        if (relativePathParts[i].equals(".")) {
            continue;
        }
        if (relativePathParts[i].equals("..")) {
            if (pathParts.length == 0) {
                throw new IllegalArgumentException("Cannot reference parent directory when path has no parent");
            }
            pathParts = Arrays.copyOf(pathParts, pathParts.length - 1);
            continue;
        }
        newPath.append("/").append(relativePathParts[i]);
    }
    return pathParts[0] + newPath.toString();
}

